-- 1) 저자 slug 교정 (doctors 테이블 실제 slug와 불일치 → 저자 미표시 버그 수정)
--    수면임플란트 글: 대표원장 / 인비절라인 글: 교정과 전문의 / 라미네이트 글: VINIQUE 센터장
UPDATE blog_posts SET author_doctor_slug='kim-seongju'  WHERE slug='sleep-implant-pain-truth';
UPDATE blog_posts SET author_doctor_slug='kim-jinduk'   WHERE slug='invisalign-10-things-before-start';
