-- 2) 신규 블로그 6편
INSERT OR IGNORE INTO blog_posts (slug, title, excerpt, content, thumbnail_url, author_doctor_slug, meta_description, meta_keywords, is_published)
VALUES
('scaling-insurance-complete-guide',
 '스케일링 보험 적용, 1년에 한 번 놓치지 마세요 — 2026 완벽 정리',
 '만 19세 이상이면 연 1회 건강보험으로 2만원대에 받을 수 있는 스케일링. 적용 기준일, 대상, 자주 하는 오해까지 치주과 전문의가 정리했습니다.',
 '<h2>스케일링 보험, 정확히 어떻게 적용되나요?</h2><p>만 19세 이상 건강보험 가입자라면 <strong>연 1회 스케일링에 건강보험이 적용</strong>됩니다. 본인부담금은 의원 기준 약 2만원 안팎으로, 비보험 시술 대비 훨씬 부담이 적습니다.</p><h3>기준일은 매년 1월 1일</h3><p>보험 적용 횟수는 <strong>매년 1월 1일에 초기화</strong>됩니다. 예를 들어 2025년 12월에 보험 스케일링을 받았다면, 2026년 1월부터 다시 1회가 생깁니다. 연말에 받고 연초에 또 받는 것도 가능하다는 뜻입니다.</p><h2>스케일링에 대한 3가지 오해</h2><h3>오해 1. "스케일링하면 이가 시리고 벌어진다"</h3><p>사실은 반대입니다. 치석이 차지하던 공간이 드러나면서 원래 상태가 보이는 것이고, 시린 증상은 대부분 1~2주 내에 사라집니다. 치석을 방치하면 잇몸뼈가 녹아 진짜로 치아가 흔들리게 됩니다.</p><h3>오해 2. "양치 잘하면 스케일링은 필요 없다"</h3><p>치석은 치태가 침 속 미네랄과 결합해 돌처럼 굳은 것으로, <strong>양치로는 절대 제거되지 않습니다</strong>. 아무리 양치를 잘해도 잇몸선 경계와 치아 사이에는 치석이 쌓입니다.</p><h3>오해 3. "아프지 않으면 안 받아도 된다"</h3><p>잇몸병은 상당히 진행될 때까지 통증이 없습니다. 잇몸에서 피가 나는 단계라면 이미 치은염이 시작된 것입니다.</p><h2>이런 분들은 6개월 주기를 권합니다</h2><ul><li>흡연자 — 치석 침착 속도가 빠르고 잇몸병 진행이 가려짐</li><li>당뇨 환자 — 치주염과 혈당이 서로 악영향</li><li>교정장치 착용 중 — 장치 주변 치태 관리가 어려움</li><li>임산부 — 호르몬 변화로 잇몸 염증에 취약</li></ul><h2>대구365치과의 스케일링</h2><p>대구365치과는 일반 스케일링 외에 <strong>에어플로우(AIRFLOW) GBT 프로토콜</strong>을 운영합니다. 미세 파우더 분사로 바이오필름과 착색까지 제거해 커피·와인·흡연 착색이 고민인 분들이 함께 선택하십니다. 월·목 야간진료(밤 9시)와 주말 진료로 직장인도 부담 없이 방문하실 수 있습니다.</p><p>더 자세한 내용은 <a href="/dictionary/scaling">스케일링 용어사전</a>과 <a href="/dictionary/calculus">치석</a> 항목을 참고하세요.</p>',
 '/static/images/treatment-room.jpg',
 'lee-seoyoung',
 '스케일링 건강보험 적용 기준(만 19세 이상 연 1회, 매년 1월 1일 초기화), 본인부담금, 자주 하는 오해 3가지를 치주과 전문의가 정리. 대구 스케일링은 대구365치과.',
 '스케일링 보험, 스케일링 가격, 스케일링 주기, 치석제거 보험, 대구 스케일링',
 1),

('wisdom-tooth-when-to-extract',
 '사랑니, 꼭 빼야 하나요? — 빼야 하는 경우와 지켜봐도 되는 경우',
 '사랑니라고 무조건 발치 대상은 아닙니다. 반드시 빼야 하는 4가지 상황과 유지해도 되는 조건, 발치 후 회복 관리까지 정리했습니다.',
 '<h2>모든 사랑니를 빼야 하는 것은 아닙니다</h2><p>사랑니가 <strong>똑바로 나서 위아래가 정상적으로 맞물리고, 칫솔이 닿아 관리가 가능하다면</strong> 굳이 뺄 이유가 없습니다. 문제는 대부분의 사랑니가 그렇지 못하다는 데 있습니다.</p><h2>반드시 발치를 고려해야 하는 4가지</h2><h3>1. 누워서 나는 매복 사랑니</h3><p>앞 어금니(7번 치아)를 밀며 누워 있는 사랑니는 <strong>7번 치아 뿌리를 녹이거나 그 사이에 충치</strong>를 만듭니다. 사랑니 때문에 멀쩡한 어금니까지 잃는 것이 최악의 시나리오입니다.</p><h3>2. 잇몸이 반복적으로 붓는 경우</h3><p>잇몸에 반쯤 덮인 사랑니 주변은 세균이 서식하기 좋은 주머니가 됩니다. 피곤할 때마다 붓고 아프기를 반복한다면(지치주위염) 발치가 근본 해결책입니다.</p><h3>3. 충치가 생긴 사랑니</h3><p>사랑니는 위치상 치료 기구 접근이 어렵고 치료해도 관리가 안 되어 재발합니다. 치료보다 발치가 합리적인 경우가 대부분입니다.</p><h3>4. 교정·보철 계획이 있는 경우</h3><p>교정 치료 전, 또는 앞 어금니 보철 계획이 있다면 사랑니 처리가 선행되어야 하는 케이스가 많습니다.</p><h2>아래 사랑니 발치가 어려운 이유</h2><p>아래턱 사랑니 뿌리는 <strong>하치조신경관</strong>과 가까운 경우가 많습니다. 신경 손상 위험을 정확히 평가하려면 파노라마만으로는 부족하고 <strong>3D CT로 뿌리와 신경의 거리</strong>를 확인해야 합니다. 대구365치과는 CT 분석 후 난이도를 설명드리고, 필요시 치관분할 등 신경 보호 술식으로 안전하게 발치합니다.</p><h2>발치 후 회복, 이것만 지키세요</h2><ol><li><strong>거즈는 2시간</strong> 꽉 물고 계세요 — 지혈의 기본입니다</li><li><strong>빨대·흡연·침 뱉기 금지</strong> — 피딱지가 떨어지면 극심한 통증(드라이소켓)이 옵니다</li><li>첫 2일은 <strong>냉찜질</strong>, 이후 부기가 남으면 온찜질</li><li>발치 부위를 혀로 건드리지 마세요</li></ol><p>관련 정보: <a href="/dictionary/wisdom-tooth-extraction">사랑니 발치</a> · <a href="/dictionary/wisdom-teeth">사랑니</a> 용어사전</p>',
 '/static/images/cta-operation-room.jpg',
 'kim-seongju',
 '사랑니를 반드시 빼야 하는 4가지 경우(매복·반복 부종·충치·교정 계획)와 유지 가능한 조건, 발치 후 드라이소켓 예방법까지. 대구 사랑니 발치는 CT 정밀 진단하는 대구365치과.',
 '사랑니 발치, 매복 사랑니, 사랑니 꼭 빼야 하나, 드라이소켓, 대구 사랑니 발치',
 1),

('implant-bone-graft-explained',
 '임플란트 뼈이식, 왜 필요하고 얼마나 아플까? — 솔직한 안내',
 '"뼈가 부족해서 뼈이식이 필요합니다"라는 말을 들으셨나요? 뼈이식이 필요한 이유, 재료 종류, 통증과 회복 기간을 있는 그대로 설명합니다.',
 '<h2>왜 뼈가 부족해지나요?</h2><p>치아를 뽑으면 그 부위 잇몸뼈는 <strong>역할을 잃고 서서히 흡수</strong>됩니다. 발치 후 1년만 지나도 뼈 폭이 눈에 띄게 줄어들고, 치주염으로 이를 잃은 경우라면 이미 뼈가 상당히 녹은 상태입니다. 임플란트는 뼈에 뿌리를 심는 치료이므로, 뼈의 양과 질이 부족하면 <strong>집을 짓기 전에 지반 공사</strong>가 필요한 것입니다.</p><h2>뼈이식 재료, 어떤 것을 쓰나요?</h2><ul><li><strong>자가골</strong> — 본인 뼈. 생착력이 가장 좋지만 채취 부위가 추가로 필요</li><li><strong>동종골·이종골</strong> — 처리된 인체 기증골 또는 동물 유래 골. 가장 널리 사용되며 안전성 검증됨</li><li><strong>합성골</strong> — 인공 합성 재료. 감염 우려가 없고 공급이 안정적</li></ul><p>대부분 두 가지 이상을 혼합해 사용하며, 케이스에 따라 재생을 돕는 차폐막을 함께 적용합니다.</p><h2>솔직히, 얼마나 아픈가요?</h2><p>뼈이식 자체는 마취 하에 진행되어 시술 중 통증은 없습니다. 다만 <strong>일반 임플란트보다 붓기와 뻐근함이 더한 것은 사실</strong>입니다. 보통 2~3일째 붓기가 최고조였다가 일주일이면 가라앉고, 처방 진통제로 조절 가능한 수준입니다. 위턱 어금니의 상악동 거상술이 동반되면 코를 세게 푸는 행동을 2주 정도 피하셔야 합니다.</p><h2>뼈이식 후 임플란트까지 얼마나 걸리나요?</h2><p>이식한 뼈가 자리 잡는 데 <strong>3~6개월</strong>이 필요합니다. 뼈 상태에 따라 뼈이식과 임플란트 식립을 동시에 진행해 기간을 줄일 수 있는 케이스도 있고, 뼈이식을 먼저 하고 기다려야 하는 케이스도 있습니다. 이 판단은 CT 상의 잔존 뼈량이 결정합니다.</p><h2>뼈이식 비용, 왜 병원마다 다른가요?</h2><p>사용 재료의 종류와 양, 차폐막 사용 여부, 시술 범위에 따라 달라집니다. 견적 비교 시 <strong>"어떤 재료를 얼마나 쓰는지"</strong>를 확인하셔야 정확한 비교가 됩니다. 대구365치과는 견적서에 재료와 범위를 명시하고, CT 화면을 함께 보며 뼈이식이 정말 필요한 상태인지부터 설명드립니다.</p><p>관련 정보: <a href="/dictionary/bone-graft">뼈이식</a> · <a href="/dictionary/sinus-lift">상악동거상술</a> · <a href="/dictionary/dental-implant">임플란트</a> 용어사전</p>',
 '/r2/images/treatments/implant-fixture.jpg',
 'kim-seongju',
 '임플란트 뼈이식이 필요한 이유, 자가골·이종골·합성골 재료 차이, 실제 통증과 회복 기간, 비용이 병원마다 다른 이유까지 솔직하게 정리. 대구 임플란트 뼈이식은 대구365치과.',
 '임플란트 뼈이식, 뼈이식 아픈가요, 뼈이식 비용, 상악동거상술, 대구 임플란트',
 1),

('root-canal-crown-necessity',
 '신경치료 후 크라운, 꼭 씌워야 하나요? — 미루면 생기는 일',
 '신경치료가 끝나고 "크라운까지 하셔야 합니다"라는 말에 과잉진료를 의심하는 분들께, 보존과 전문의가 크라운이 필수인 이유를 설명합니다.',
 '<h2>신경치료를 마친 치아는 "마른 나뭇가지"입니다</h2><p>신경치료는 치아 내부의 신경·혈관을 제거하는 치료입니다. 혈관이 사라진 치아는 <strong>수분과 영양 공급이 끊겨 탄력을 잃고 잘 부러지는 상태</strong>가 됩니다. 생나무 가지는 휘어지지만 마른 가지는 뚝 부러지는 것과 같은 원리입니다.</p><p>게다가 신경치료 과정에서 충치 부위와 치아 중앙부를 상당량 제거하기 때문에, 남은 치아 벽은 얇아져 있습니다. 이 상태로 어금니에 가해지는 수십 kg의 씹는 힘을 견디라는 것은 무리한 요구입니다.</p><h2>크라운을 미루면 생기는 일</h2><h3>최악의 시나리오: 수직 파절</h3><p>치아가 뿌리 방향으로 세로로 쪼개지는 것을 수직 파절이라고 합니다. <strong>세로로 갈라진 치아는 살릴 방법이 없어 발치</strong>해야 합니다. 몇 달에 걸친 신경치료가 한순간에 무의미해지고, 임플란트 비용까지 더해집니다.</p><h3>임시충전재는 "임시"입니다</h3><p>신경치료 후 채워둔 임시충전재는 수 주 안에 마모되고 틈이 생깁니다. 그 틈으로 세균이 들어가면 <strong>소독해둔 신경관이 재감염</strong>되어 신경치료를 처음부터 다시 하거나, 그마저 어려우면 발치로 이어집니다.</p><h2>"당장 안 아픈데요?"가 함정입니다</h2><p>신경을 제거한 치아는 <strong>통증을 느끼지 못합니다</strong>. 금이 가도, 재감염이 시작되어도 신호가 없습니다. 아프지 않다는 것이 괜찮다는 뜻이 아닌 유일한 치아가 바로 신경치료 받은 치아입니다.</p><h2>크라운 종류는 어떻게 고르나요?</h2><ul><li><strong>지르코니아</strong> — 강도와 심미성을 모두 갖춰 현재 가장 널리 사용</li><li><strong>골드</strong> — 자연치아와 유사한 마모도, 어금니에 여전히 우수한 선택</li><li><strong>PFM(금속+도자기)</strong> — 비용 장점, 잇몸 경계 변색 가능성</li></ul><p>대구365치과는 원내 디지털 기공 시스템으로 크라운을 자체 제작해 정밀도를 관리하며, 신경치료 후 2~4주 내 크라운 완료를 권장 일정으로 안내드립니다.</p><p>관련 정보: <a href="/dictionary/root-canal-treatment">신경치료</a> · <a href="/dictionary/crown">크라운</a> · <a href="/dictionary/zirconia">지르코니아</a> 용어사전</p>',
 '/static/images/detail-crown.jpg',
 'kim-sangwon',
 '신경치료 후 크라운이 필수인 이유 — 수직 파절 위험, 임시충전재의 한계, 통증 없는 재감염. 크라운 종류별 비교까지 보존과 전문의가 설명. 대구 신경치료는 대구365치과.',
 '신경치료 후 크라운, 신경치료 크라운 꼭, 크라운 종류, 지르코니아 크라운, 대구 신경치료',
 1),

('bruxism-nightguard-guide',
 '아침마다 턱이 뻐근하다면 — 이갈이 자가진단과 나이트가드의 모든 것',
 '본인은 모르는 사이 치아를 파괴하는 이갈이. 자가진단 체크리스트, 방치했을 때의 결과, 나이트가드 맞춤 제작 과정을 안내합니다.',
 '<h2>이갈이, 내가 하는지 어떻게 알까요?</h2><p>이갈이는 수면 중에 일어나 <strong>본인은 대부분 자각하지 못합니다</strong>. 아래 항목 중 2개 이상 해당된다면 이갈이를 의심해 보세요.</p><ul><li>아침에 턱이 뻐근하거나 관자놀이 쪽 두통이 있다</li><li>어금니 씹는 면이 평평하게 닳아 있다</li><li>치아에 미세한 금(크랙)이 있다는 말을 들었다</li><li>차가운 것에 여러 치아가 동시에 시리다</li><li>볼 안쪽 살에 씹은 자국(백선)이 있다</li><li>가족이 이가는 소리를 들었다고 한다</li></ul><h2>이갈이의 힘은 상상 이상입니다</h2><p>수면 중 이갈이의 힘은 <strong>평소 씹는 힘의 2~10배</strong>에 달합니다. 낮에는 뇌가 씹는 힘을 제어하지만 수면 중에는 이 제어가 풀리기 때문입니다. 이 힘이 매일 밤 치아에 가해지면 법랑질 마모 → 시린 증상 → 크랙 → 파절 순으로 진행되고, 턱관절(TMJ)에도 부담이 누적됩니다.</p><p>특히 <strong>임플란트·크라운·라미네이트를 하신 분</strong>은 주의가 필요합니다. 보철물은 자연치아의 미세한 완충 구조(치주인대)가 없거나 다르기 때문에, 이갈이 힘이 그대로 전달되어 파손 위험이 훨씬 높습니다.</p><h2>나이트가드는 어떻게 치아를 지키나요?</h2><p>나이트가드는 이갈이 자체를 없애는 장치가 아닙니다. 대신 <strong>갈리는 힘을 치아 대신 장치가 흡수</strong>하도록 만들어, 마모·파절·턱관절 손상을 예방합니다. 치아를 위한 보험이라고 이해하시면 정확합니다.</p><h3>기성품 vs 맞춤 제작</h3><p>시중 기성품은 두껍고 헐거워 수면 중 빠지거나 오히려 턱 위치를 불안정하게 만들 수 있습니다. 치과 맞춤형은 본인 치아 본을 떠 제작해 얇고 정확하게 맞으며, <strong>착용 후 교합 조정</strong>까지 이루어져 턱관절 부담을 줄입니다.</p><h2>제작 과정 (2회 내원)</h2><ol><li><strong>1차</strong> — 구강 검진, 이갈이 흔적 확인, 치아 본뜨기(또는 구강스캔)</li><li><strong>2차</strong> — 장치 시적, 교합 조정, 관리법 안내</li></ol><p>대구365치과는 이갈이 흔적과 턱관절 상태를 함께 평가해 나이트가드 두께와 형태를 케이스별로 설계합니다. 야간·주말 진료로 바쁜 직장인도 2회 방문으로 완성할 수 있습니다.</p><p>관련 정보: <a href="/dictionary/mouthguard">마우스가드</a> · <a href="/dictionary/tmd">턱관절장애</a> 용어사전</p>',
 '/static/images/doctor-mood.jpg',
 'jung-jaeheon',
 '이갈이 자가진단 체크리스트 6가지, 방치 시 치아 마모·파절·턱관절 손상, 나이트가드 기성품과 맞춤형 차이, 제작 과정까지. 대구 나이트가드는 대구365치과.',
 '이갈이, 나이트가드, 이갈이 치료, 아침 턱 뻐근, 나이트가드 가격, 대구 나이트가드',
 1),

('whitening-vs-laminate-choice',
 '치아 미백 vs 라미네이트 — 내 치아에 맞는 선택은?',
 '누런 치아가 고민일 때 미백과 라미네이트 중 무엇이 맞을까요? 변색 원인별 적합한 치료, 비용·기간·유지력 비교표로 정리했습니다.',
 '<h2>먼저, 변색의 원인부터 알아야 합니다</h2><p>같은 "누런 치아"라도 원인이 다르면 해법이 다릅니다.</p><h3>미백이 잘 듣는 변색</h3><ul><li>커피·와인·흡연 등 <strong>외인성 착색</strong></li><li>나이가 들며 전체적으로 어두워진 <strong>생리적 변색</strong></li></ul><h3>미백으로 한계가 있는 변색</h3><ul><li>테트라사이클린(항생제) 변색 — 띠 모양의 회갈색 변색</li><li>신경이 죽어 어두워진 치아 — 실활치 미백 또는 보철 필요</li><li>법랑질 형성부전 등 <strong>구조적 변색</strong></li></ul><h2>미백 vs 라미네이트 한눈에 비교</h2><p><strong>치아 미백</strong>은 과산화물 약제로 치아 내부 색소를 분해하는 시술입니다. 치아를 깎지 않고 원래 구조를 그대로 유지하며, 전문가 미백 기준 1~3회 내원으로 밝아집니다. 다만 색만 바꿀 수 있고, 효과는 개인차가 있으며 시간이 지나면 서서히 재착색되어 <strong>1~2년 주기의 터치업</strong>이 필요합니다.</p><p><strong>라미네이트</strong>는 치아 앞면에 얇은 세라믹을 부착하는 시술입니다. 색뿐 아니라 <strong>모양·크기·벌어짐까지 한 번에 개선</strong>되고 세라믹은 재착색되지 않습니다. 대신 법랑질을 얇게 다듬는 비가역적 치료이고 비용이 높으며, 이갈이가 있다면 파절 관리가 필요합니다.</p><h2>이렇게 선택하세요</h2><ol><li><strong>색만 고민 + 치아 모양은 만족</strong> → 미백 먼저. 가장 보존적인 선택입니다.</li><li><strong>색 + 모양·벌어짐·비뚤어짐까지 고민</strong> → 라미네이트가 한 번에 해결합니다.</li><li><strong>항생제 변색·실활치</strong> → 미백 단독으로는 한계, 라미네이트 또는 실활치 미백 병행을 상담하세요.</li><li><strong>예산이 고민</strong> → 전체 미백 후 문제 치아 1~2개만 라미네이트하는 조합도 가능합니다.</li></ol><h2>순서가 중요합니다</h2><p>미백과 라미네이트를 병행한다면 <strong>미백을 먼저</strong> 해야 합니다. 라미네이트 세라믹은 색이 변하지 않으므로, 미백으로 밝아진 치아 색에 맞춰 세라믹 색을 제작해야 전체가 조화롭습니다.</p><p>대구365치과 VINIQUE 센터는 디지털 스마일 디자인(DSD)으로 시술 전 결과를 시뮬레이션해 보여드리고, 변색 원인 진단부터 미백·라미네이트·조합 치료까지 케이스에 맞는 최소 개입 방안을 제시합니다.</p><p>관련 정보: <a href="/dictionary/teeth-whitening">치아미백</a> · <a href="/dictionary/laminate-veneer">라미네이트</a> · <a href="/dictionary/veneer">베니어</a> 용어사전</p>',
